declare(strict_types=1);require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/auth.php';require_once __DIR__.'/../../src/ui.php';$u=require_student();$pdo=db();$error=null;$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if($name==='')throw new RuntimeException('Nome obrigatório.');$pdo->beginTransaction();$pdo->prepare("UPDATE app_users SET name=:n,email=:e,updated_at=NOW() WHERE id=:i")->execute(['n'=>$name,'e'=>$email?:null,'i'=>$u['id']]);$pdo->prepare("UPDATE students SET name=:n,email=:e,updated_at=NOW() WHERE id=:i")->execute(['n'=>$name,'e'=>$email?:null,'i'=>$u['student_id']]);$pdo->commit();audit_log('profile_updated','app_user',$u['id']);$success='Perfil atualizado.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$s=$pdo->prepare("SELECT u.name,u.email,u.phone,u.username,u.last_login_at,s.created_at student_since,COALESCE(sp.overall_level,'PRE-A1') overall_level,COALESCE(sp.xp,0) xp FROM app_users u JOIN students s ON s.id=u.student_id LEFT JOIN student_profiles sp ON sp.student_id=s.id WHERE u.id=:i");$s->execute(['i'=>$u['id']]);$d=$s->fetch();$pageTitle='Meu perfil';$pageSubtitle='Mantenha seus dados de acesso e identificação atualizados.';require __DIR__.'/../../templates/header.php';?>
<?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?>
<section class="student-head"><div style="display:flex;align-items:center;gap:16px"><div class="avatar avatar-lg"><?=e(ui_initials($d['name']))?></div><div><span class="badge dark"><?=e($d['overall_level'])?></span><h2><?=e($d['name'])?></h2><div class="label">Aluno desde <?=e(ui_date_only($d['student_since']))?></div></div></div><div class="hero-stat"><strong><?= (int)$d['xp']?> XP</strong><span>progresso acumulado</span></div></section>
<div class="grid-2 equal"><section class="panel"><div class="panel-head"><div><h2>Dados pessoais</h2><p>Nome e e-mail aparecem nos portais e relatórios.</p></div></div><form method="post"><?=csrf_field()?><div class="form-row"><label>Nome</label><input name="name" value="<?=e($d['name'])?>" required></div><div class="form-row"><label>E-mail</label><input type="email" name="email" value="<?=e($d['email']??'')?>"></div><div class="form-row"><label>Telefone</label><input value="<?=e($d['phone']??'')?>" disabled><small class="form-help">O telefone está vinculado à integração do WhatsApp.</small></div><div class="form-actions"><button class="btn btn-primary">Salvar perfil</button></div></form></section><section class="panel"><div class="panel-head"><div><h2>Acesso e segurança</h2><p>Informações vinculadas ao seu usuário.</p></div></div><div class="info-grid"><div class="info-item"><span>Usuário</span><strong><?=e($d['username']??'—')?></strong></div><div class="info-item"><span>Último acesso</span><strong><?=e(ui_date($d['last_login_at']))?></strong></div></div><div class="list-card" style="margin-top:14px"><strong>Senha</strong><p>Atualize sua senha periodicamente e não compartilhe seu acesso.</p><a class="btn btn-secondary btn-sm" href="/change-password.php" style="margin-top:10px">Alterar senha</a></div></section></div>
